WITH "per" AS (SELECT "t0"."customer_id" AS "customer_id", COUNT(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN 1 END) AS "orders" FROM "sales"."orders" AS "t0" WHERE ("t0"."status" = 'DONE') AND ("t0"."customer_id" IS NOT NULL) AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t0"."customer_id"), "summary" AS (SELECT CASE WHEN "per"."orders" < 3 THEN '0-2' WHEN "per"."orders" >= 3 THEN '3+' END AS "orders_range", COUNT(*) AS "customers", MAX("per"."orders") AS "max_orders", MIN("per"."orders") AS "__order" FROM "per" GROUP BY CASE WHEN "per"."orders" < 3 THEN '0-2' WHEN "per"."orders" >= 3 THEN '3+' END), "medians" AS (SELECT CASE WHEN "per"."orders" < 3 THEN '0-2' WHEN "per"."orders" >= 3 THEN '3+' END AS "orders_range", MEDIAN("per"."orders") AS "median_orders" FROM "per" GROUP BY CASE WHEN "per"."orders" < 3 THEN '0-2' WHEN "per"."orders" >= 3 THEN '3+' END) SELECT "summary"."orders_range" AS "orders_range", "summary"."customers" AS "customers", "medians"."median_orders" AS "median_orders", "summary"."max_orders" AS "max_orders" FROM "summary" JOIN "medians" ON "summary"."orders_range" IS NOT DISTINCT FROM "medians"."orders_range" ORDER BY "summary"."__order" ASC LIMIT 1000
